import React, { useState } from 'react';
import './MenuForms.css';
import Ahorro from '../../Subs/Ahorro'; // Asegúrate de que la ruta es correcta

const MenuForms = ({ user }) => {  // Asegúrate de pasar el prop 'user'
    const [info, setInfo] = useState('');
    const [selectedForm, setSelectedForm] = useState(null);

    const scrollToInfo = () => {
        const infoSection = document.getElementById('info-section');
        if (infoSection) {
            infoSection.scrollIntoView({ behavior: 'smooth' });
        }
    };

    const handleAhorroClick = () => {
        setInfo('Generar Ahorro');
        setSelectedForm('ahorro'); // Cambia el estado para mostrar el formulario correspondiente
        scrollToInfo();
    };

    const handleJubilacionClick = () => {
        setInfo('Plan de Jubilación');
        setSelectedForm('jubilacion');
        scrollToInfo();
    };

    const handleMetasClick = () => {
        setInfo('Metas Largo/Corto Plazo');
        setSelectedForm('metas');
        scrollToInfo();
    };

    return (
        <div className="menu-form">
            <h2>¿En qué puede ayudarte FinanTec?</h2>
            <div className="menu-options">
                <div className="saving-box green" onClick={handleAhorroClick}>
                    <div className="icon">💰</div>
                    <span>Generar Ahorro</span>
                </div>
                <div className="saving-box blue" onClick={handleJubilacionClick}>
                    <div className="icon">🏦</div>
                    <span>Plan de Jubilación</span>
                </div>
                <div className="saving-box pink" onClick={handleMetasClick}>
                    <div className="icon">🎯</div>
                    <span>Metas Largo/Corto Plazo</span>
                </div>
            </div>

            {/* Sección de información */}
            <div id="info-section" className="info-section">
                <h3>Información sobre {info || 'FinanTec'}</h3>
                <p>
                    {info === 'Generar Ahorro' && (
                        'FinanTec es tu aliado en el camino hacia una mejor salud financiera...'
                    )}
                    {info === 'Plan de Jubilación' && (
                        'El Plan de Jubilación de FinanTec te ofrece la guía necesaria para asegurar tu futuro...'
                    )}
                    {info === 'Metas Largo/Corto Plazo' && (
                        'Con nuestras herramientas, podrás definir y alcanzar tus metas de ahorro...'
                    )}
                </p>
            </div>

            {/* Renderizar el componente Ahorro solo si está seleccionado */}
            {selectedForm === 'ahorro' && <Ahorro user={user} />}
            {/* Agrega el renderizado de otros formularios según sea necesario */}
        </div>
    );
};

export default MenuForms;
